-- 重複していた予定を片付ける・その2（2026-10-04 柴野「重複は絶対に避けたい」）。96組・外す316件。
-- その1（sql/2026-10-04-duplicates-cleanup.sql・手で1組ずつ仕分けた57組）の後に流す。どちらからでも結果は同じ。
--
-- 対象: ボットが入れた予定のうち、同じ作品で「名前・発売日・値段が同じ・同じ店・どちらかがキャラ別のリンクを持つ」か
--   「名前と値段が同じ・別の店・発売日が7日以内（作品名を除いて10文字以上の名前）」のもの。
--   一覧のまとめ（api/_listgroup.ts）が全キャラでは成り立たずに分けたまとまりが、同じ名前の予定として並んでいた
--   （18TRIP 硬質カードホルダーが6件・鬼滅の刃 アクリルキーホルダーが7件など。ほとんどが同じ時刻に入っている）。
--   見る人には区別がつかないので1つにする。キャラ名はもう購入リンクに付いている。
--   これから入る分は api/_crawl.ts の findSameLine で同じ条件のときに1つへまとめる（同じコミット）。
-- 残す: 購入リンクが一番多いもの（同じなら先に入ったもの）。外す: ほか … 消さずに pool = 1。
--
